   fn log_refused(seed: &str, reason: ClaimRefusal) {
       log_info("practice.claim.refused", json!({ "seed": seed, "reason": reason }));
   }

   /// #2884: a refusal made before the burn, counted in `tx` (which wrote nothing else) and
   /// committed, logged and answered. A failed count is only logged: the answer is as before.
   async fn refuse_unburned(tx: StoreResult<Tx<'_>>, seed: &str, reason: ClaimRefusal) -> ApiResult {
       let counted: StoreResult<()> = async move {
           let mut tx = tx?;
           tx.economy_practice_claim_count(ClaimBucket::Refused(reason), now_ms()).await?;
           tx.commit().await
       }
       .await;
       if let Err(error) = counted {
           log_warn(
               "practice.claim.countFailed",
               json!({ "seed": seed, "reason": reason, "message": error.to_string() }),
           );
       }
       log_refused(seed, reason);
       refused(reason)
   }
   ```
